import{_ as a,c as i,o as n,ag as r}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/introduction.md","filePath":"fr/guide/introduction.md","lastUpdated":1794112334000}'),t={name:"fr/guide/introduction.md"};function s(o,e,l,u,d,c){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><h2 id="a-propos-de-nicasa" tabindex="-1">À propos de Nicasa <a class="header-anchor" href="#a-propos-de-nicasa" aria-label="Permalink to &quot;À propos de Nicasa&quot;">​</a></h2><p>Nicasa est une visionneuse d&#39;images de bureau moderne et un outil de capture d&#39;écran conçu pour la rapidité, la simplicité et de puissantes capacités d&#39;édition. Conçu exclusivement pour macOS, Nicasa apporte une expérience de visualisation d&#39;images fluide et moderne sur votre bureau.</p><h2 id="fonctionnalites-cles" tabindex="-1">Fonctionnalités clés <a class="header-anchor" href="#fonctionnalites-cles" aria-label="Permalink to &quot;Fonctionnalités clés&quot;">​</a></h2><h3 id="🖼️-une-meilleure-facon-de-voir-les-images" tabindex="-1">🖼️ <strong>Une meilleure façon de voir les images</strong> <a class="header-anchor" href="#🖼️-une-meilleure-facon-de-voir-les-images" aria-label="Permalink to &quot;🖼️ **Une meilleure façon de voir les images**&quot;">​</a></h3><p>Ouvrez vos images instantanément dans une interface claire et ciblée. Sans distraction, sans encombrement : juste votre contenu, joliment présenté dès l&#39;ouverture.</p><h3 id="📸-captures-d-ecran" tabindex="-1">📸 <strong>Captures d&#39;écran</strong> <a class="header-anchor" href="#📸-captures-d-ecran" aria-label="Permalink to &quot;📸 **Captures d&#39;écran**&quot;">​</a></h3><p>Capturez n&#39;importe quelle partie de votre écran en quelques secondes. Avec des outils de capture rapides et précis intégrés à Nicasa, enregistrer et partager des idées visuelles n&#39;a jamais été aussi simple.</p><h3 id="🤖-editeur-d-images-par-ia" tabindex="-1">🤖 <strong>Éditeur d&#39;images par IA</strong> <a class="header-anchor" href="#🤖-editeur-d-images-par-ia" aria-label="Permalink to &quot;🤖 **Éditeur d&#39;images par IA**&quot;">​</a></h3><p>Améliorez et affinez vos images avec de puissants outils d&#39;IA. Des ajustements rapides à l&#39;édition intelligente, Nicasa vous aide à transformer vos images sans effort.</p><h3 id="🔍-mode-superposition-transparente" tabindex="-1">🔍 <strong>Mode superposition transparente</strong> <a class="header-anchor" href="#🔍-mode-superposition-transparente" aria-label="Permalink to &quot;🔍 **Mode superposition transparente**&quot;">​</a></h3><p>Un outil puissant pour les designers et les artistes : épinglez une image au-dessus de toutes les fenêtres avec une transparence réglable, parfait pour le décalquage, le travail de référence et la comparaison d&#39;interfaces.</p><h3 id="🌐-integration-de-l-extension-chrome" tabindex="-1">🌐 <strong>Intégration de l&#39;extension Chrome</strong> <a class="header-anchor" href="#🌐-integration-de-l-extension-chrome" aria-label="Permalink to &quot;🌐 **Intégration de l&#39;extension Chrome**&quot;">​</a></h3><p>Connectez-vous de façon transparente à l&#39;extension Chrome de Nicasa pour voir toutes les images de n&#39;importe quel site web au même endroit. Extrayez, parcourez et ouvrez les images directement dans Nicasa pour une expérience plus rapide et plus immersive.</p><h3 id="🎨-un-design-fluide-et-intuitif" tabindex="-1">🎨 <strong>Un design fluide et intuitif</strong> <a class="header-anchor" href="#🎨-un-design-fluide-et-intuitif" aria-label="Permalink to &quot;🎨 **Un design fluide et intuitif**&quot;">​</a></h3><p>Propulsé par une technologie de nouvelle génération, Nicasa offre des transitions fluides, un rendu net et un design d&#39;interaction réfléchi.</p><h2 id="configuration-requise" tabindex="-1">Configuration requise <a class="header-anchor" href="#configuration-requise" aria-label="Permalink to &quot;Configuration requise&quot;">​</a></h2><ul><li><strong>Système d&#39;exploitation</strong> : macOS 10.13 ou version ultérieure</li><li><strong>Mémoire</strong> : 4 Go de RAM minimum, 8 Go recommandés</li><li><strong>Stockage</strong> : 54,5 Mo pour l&#39;installation</li><li><strong>Écran</strong> : résolution minimale de 1280x720</li></ul><h2 id="langues-prises-en-charge" tabindex="-1">Langues prises en charge <a class="header-anchor" href="#langues-prises-en-charge" aria-label="Permalink to &quot;Langues prises en charge&quot;">​</a></h2><p>Nicasa prend en charge de nombreuses langues, dont l&#39;anglais, le chinois simplifié, le chinois traditionnel, le japonais, le français, le coréen, l&#39;allemand, l&#39;espagnol, l&#39;italien, le vietnamien, le thaï, l&#39;hindi, le turc, le russe, le portugais, le néerlandais, l&#39;allemand (Suisse), le finnois, le malais, le grec, le norvégien, l&#39;indonésien, le hongrois, le danois et l&#39;ukrainien.</p><h2 id="premiers-pas" tabindex="-1">Premiers pas <a class="header-anchor" href="#premiers-pas" aria-label="Permalink to &quot;Premiers pas&quot;">​</a></h2><p>Si vous débutez avec Nicasa, commencez par le <a href="/fr/guide/installation.html">guide d&#39;installation</a> pour faire fonctionner l&#39;application sur votre Mac.</p>',22)])])}const g=a(t,[["render",s]]);export{m as __pageData,g as default};
